#include <Arduino.h>
#include <M5Cardputer.h>
#include <SPI.h>
#include <SD.h>
#include <AnimatedGIF.h>
#include <WiFi.h>
#include <Preferences.h>
#include <time.h>
#include <vector>
#include <algorithm>

namespace {
constexpr int W=240,H=135,SD_CS=12,SD_MOSI=14,SD_SCLK=40,SD_MISO=39;
constexpr char ROOT[]="/CHAOS_TV/LIBRARIES", WIFI_FILE[]="/CHAOS_TV/CONFIG/wifi.txt";
constexpr char TZ[]="CET-1CEST,M3.5.0,M10.5.0/3";
AnimatedGIF gif; File gifFile; Preferences prefs;
std::vector<String> folders, files;
int folderIndex=0,fileIndex=0; bool sdOK=false,playing=false,paused=false,configured=false,manualTime=false;
uint16_t frame[W*H], shown[W*H], restore[180*70];
uint8_t colorIndex=0; const uint16_t colors[]={0x07ff,0x07e0,0xfd20,0xf800,0xf81f,0x249f,0xffff};
uint32_t nextFrame=0,lastSecond=UINT32_MAX; bool gifEnded=false;
uint16_t dim(uint16_t c,uint8_t p){return (((((c>>11)&31)*p/100)<<11)|(((((c>>5)&63)*p/100)<<5))|((c&31)*p/100));}
void screenText(const String&a,const String&b="",const String&c=""){auto&d=M5Cardputer.Display;d.fillScreen(TFT_BLACK);d.setTextColor(TFT_CYAN,TFT_BLACK);d.drawString("FREEzzz NEON CLOCK",4,5);d.setTextColor(TFT_WHITE,TFT_BLACK);d.drawString(a,4,27);d.setTextColor(TFT_YELLOW,TFT_BLACK);d.drawString(b,4,52);d.setTextColor(TFT_LIGHTGREY,TFT_BLACK);d.drawString(c,4,76);d.drawString("ENTER = SELECT",4,116);}
char key(){for(;;){M5Cardputer.update();if(M5Cardputer.Keyboard.isChange()&&M5Cardputer.Keyboard.isPressed()){auto k=M5Cardputer.Keyboard.keysState();if(k.enter)return '\n';if(k.del)return '\b';if(!k.word.empty())return k.word[0];}delay(8);}}
void scanFolders(){folders.clear();File d=SD.open(ROOT);if(!d)return;for(File e=d.openNextFile();e;e=d.openNextFile()){if(e.isDirectory()){String n=e.name();int p=n.lastIndexOf('/');if(p>=0)n=n.substring(p+1);if(n.length())folders.push_back(n);}e.close();}d.close();std::sort(folders.begin(),folders.end());if(folderIndex>=(int)folders.size())folderIndex=0;}
void scanFiles(){files.clear();if(folders.empty())return;File d=SD.open(String(ROOT)+"/"+folders[folderIndex]);if(!d)return;for(File e=d.openNextFile();e;e=d.openNextFile()){if(!e.isDirectory()){String n=e.name();n.toLowerCase();if(n.endsWith(".gif")){n=e.name();int p=n.lastIndexOf('/');if(p>=0)n=n.substring(p+1);files.push_back(n);}}e.close();}d.close();std::sort(files.begin(),files.end());if(fileIndex>=(int)files.size())fileIndex=0;}
void* openGif(const char*n,int32_t*s){gifFile=SD.open(n,FILE_READ);if(!gifFile)return nullptr;*s=gifFile.size();return &gifFile;}
void closeGif(void*h){File*f=(File*)h;if(f&&*f)f->close();}
int32_t readGif(GIFFILE*f,uint8_t*b,int32_t n){File*x=(File*)f->fHandle;return x&&*x?x->read(b,n):0;}
int32_t seekGif(GIFFILE*f,int32_t p){File*x=(File*)f->fHandle;return x&&*x&&x->seek(p)?p:0;}
void drawGif(GIFDRAW*d){if(!d||!d->pPixels||!d->pPalette)return;int y=d->iY+d->y;if(y<0||y>=H)return;auto*ix=d->pPixels;auto*pal=(uint16_t*)d->pPalette;for(int i=0;i<d->iWidth;i++){int x=d->iX+i;if(x<0||x>=W)continue;uint8_t q=ix[i];if(d->ucHasTransparency&&q==d->ucTransparent)continue;frame[y*W+x]=pal[q];}}
bool startGif(){if(files.empty())return false;if(gif.getCanvasWidth())gif.close();if(gifFile)gifFile.close();String p=String(ROOT)+"/"+folders[folderIndex]+"/"+files[fileIndex];gif.begin(GIF_PALETTE_RGB565_LE);if(!gif.open(p.c_str(),openGif,closeGif,readGif,seekGif,drawGif))return false;memset(frame,0,sizeof(frame));nextFrame=0;gifEnded=false;playing=true;return true;}
bool wifi(){String ssid,pass;File f=SD.open(WIFI_FILE);if(f){while(f.available()){String l=f.readStringUntil('\n');l.trim();if(l.startsWith("SSID="))ssid=l.substring(5);if(l.startsWith("PASSWORD="))pass=l.substring(9);}f.close();}if(!ssid.length())return false;WiFi.mode(WIFI_STA);WiFi.setSleep(false);WiFi.begin(ssid.c_str(),pass.c_str());uint32_t t=millis();while(WiFi.status()!=WL_CONNECTED&&millis()-t<15000)delay(100);if(WiFi.status()!=WL_CONNECTED)return false;configTzTime(TZ,"pool.ntp.org","time.google.com","time.cloudflare.com");t=millis();struct tm ti;while(millis()-t<15000&&!getLocalTime(&ti,100)){}return getLocalTime(&ti,0);}
bool manual(){String v;while(v.length()<12){screenText("MANUAL DATE / TIME","HHMMDDMMYYYY",v+"_  DEL=BACK");char c=key();if(c=='\b'){if(v.length())v.remove(v.length()-1);}else if(c>='0'&&c<='9')v+=c;}struct tm t={};t.tm_hour=v.substring(0,2).toInt();t.tm_min=v.substring(2,4).toInt();t.tm_mday=v.substring(4,6).toInt();t.tm_mon=v.substring(6,8).toInt()-1;t.tm_year=v.substring(8).toInt()-1900;t.tm_isdst=-1;if(t.tm_hour>23||t.tm_min>59||t.tm_mday<1||t.tm_mday>31||t.tm_mon<0||t.tm_mon>11||t.tm_year<120)return false;setenv("TZ",TZ,1);tzset();time_t e=mktime(&t);if(e<1700000000)return false;struct timeval tv={e,0};settimeofday(&tv,nullptr);prefs.begin("neonclock",false);prefs.putULong64("epoch",e);prefs.putBool("manual",true);prefs.end();manualTime=true;return true;}
void wizard(){if(folders.empty()){SD.mkdir(String(ROOT)+"/USER");scanFolders();}int sel=0;while(!folders.empty()){screenText("SELECT GIF FOLDER",folders[sel],"A/D CHANGE");char c=key();if(c=='a')sel=(sel+folders.size()-1)%folders.size();else if(c=='d')sel=(sel+1)%folders.size();else if(c=='\n')break;}folderIndex=sel;scanFiles();screenText("DATE AND TIME","1 WIFI / NTP","2 MANUAL");char c=key();bool ok=(c=='1')&&wifi();if(ok)manualTime=false;else while(!manual())screenText("INVALID DATE","TRY AGAIN","HHMMDDMMYYYY");prefs.begin("neonclock",false);prefs.putBool("configured",true);prefs.putInt("folder",folderIndex);prefs.putBool("manual",manualTime);prefs.end();configured=true;}
void drawDigit(int x,int y,int n,uint16_t c){static const uint8_t m[]={63,6,91,79,102,109,125,7,127,111};uint8_t b=m[n%10];auto seg=[&](int bit,int sx,int sy,int sw,int sh){if(b&(1<<bit)){M5Cardputer.Display.fillRoundRect(sx-2,sy-2,sw+4,sh+4,3,dim(c,25));M5Cardputer.Display.fillRoundRect(sx,sy,sw,sh,2,dim(c,90));}};seg(0,x+8,y,23,7);seg(1,x+31,y+6,7,23);seg(2,x+31,y+37,7,23);seg(3,x+8,y+60,23,7);seg(4,x,y+37,7,23);seg(5,x,y+6,7,23);seg(6,x+8,y+30,23,7);}
void overlay(){struct tm t;if(!getLocalTime(&t,0))return;uint32_t s=t.tm_yday*86400+t.tm_hour*3600+t.tm_min*60+t.tm_sec;if(s==lastSecond)return;lastSecond=s;constexpr int x=24,y=29;uint16_t c=colors[colorIndex];drawDigit(x,y,t.tm_hour/10,c);drawDigit(x+42,y,t.tm_hour%10,c);M5Cardputer.Display.fillCircle(x+87,y+22,4,c);M5Cardputer.Display.fillCircle(x+87,y+47,4,c);drawDigit(x+103,y,t.tm_min/10,c);drawDigit(x+145,y,t.tm_min%10,c);char date[20];snprintf(date,sizeof(date),"%02d.%02d.%04d",t.tm_mday,t.tm_mon+1,t.tm_year+1900);M5Cardputer.Display.setTextColor(dim(c,75),TFT_BLACK);M5Cardputer.Display.drawString(date,5,117);M5Cardputer.Display.drawString(WiFi.status()==WL_CONNECTED?"WIFI":"LOCAL",205,117);}
void restoreClock(){constexpr int x=28,y=27,w=180,h=70;for(int j=0;j<h;j++)for(int i=0;i<w;i++)restore[j*w+i]=dim(shown[(y+j)*W+x+i],35);M5Cardputer.Display.pushImage(x,y,w,h,restore);}
void setup(){auto c=M5.config();c.serial_baudrate=115200;M5Cardputer.begin(c,true);M5Cardputer.Display.setRotation(0);M5Cardputer.Display.setBrightness(190);M5Cardputer.Display.fillScreen(TFT_BLACK);setenv("TZ",TZ,1);tzset();prefs.begin("neonclock",true);configured=prefs.getBool("configured",false);folderIndex=prefs.getInt("folder",0);manualTime=prefs.getBool("manual",false);time_t e=prefs.getULong64("epoch",0);prefs.end();if(e>1700000000){struct timeval tv={e,0};settimeofday(&tv,nullptr);}SPI.begin(SD_SCLK,SD_MISO,SD_MOSI,SD_CS);sdOK=SD.begin(SD_CS,SPI,20000000);if(!sdOK){screenText("MICROSD ERROR","CHECK CARD");return;}SD.mkdir("/CHAOS_TV");SD.mkdir(ROOT);SD.mkdir("/CHAOS_TV/CONFIG");scanFolders();scanFiles();if(!configured)wizard();else if(!manualTime)wifi();scanFiles();if(!files.empty())startGif();}
void loop(){M5Cardputer.update();if(M5Cardputer.Keyboard.isChange()&&M5Cardputer.Keyboard.isPressed()){auto k=M5Cardputer.Keyboard.keysState();if(k.enter)paused=!paused;if(!k.word.empty()){char q=k.word[0];if(q=='n'&&!files.empty()){fileIndex=(fileIndex+1)%files.size();startGif();}if(q=='1')colorIndex=(colorIndex+1)%7;}}if(playing&&!paused&&millis()>=nextFrame){int d=80;bool more=gif.playFrame(false,&d);nextFrame=millis()+constrain(d,20,1000);if(!more)gifEnded=true;for(int i=0;i<W*H;i++)shown[i]=dim(frame[i],35);M5Cardputer.Display.pushImage(0,0,W,H,shown);lastSecond=UINT32_MAX;restoreClock();overlay();if(gifEnded){if(files.size()>1){fileIndex=(fileIndex+1)%files.size();startGif();}else{gif.close();startGif();}}}else if(!playing){M5Cardputer.Display.setTextColor(TFT_CYAN,TFT_BLACK);M5Cardputer.Display.drawString("ADD GIF TO /CHAOS_TV/LIBRARIES/USER",2,10);}overlay();delay(2);}
}
